if($personnelId>0){
 $q=$pdo->prepare("SELECT w.id,w.contrat_id,w.etape,w.ordre,w.statut,w.signe_at,c.reference,c.objet,c.statut contrat_statut,ch.code chantier_code,ch.titre chantier_titre,COALESCE(NULLIF(f.nom_commercial,''),f.raison_sociale,CONCAT(f.person_first_name,' ',f.person_last_name)) fournisseur_nom FROM contrat_workflow_etape w JOIN contrat_sous_traitance c ON c.id=w.contrat_id JOIN chantier_banamur ch ON ch.id=c.chantier_id JOIN fournisseur_banamur f ON f.id_fournisseur=c.fournisseur_id WHERE w.signataire_personnel_id=? ORDER BY CASE w.statut WHEN 'en_cours' THEN 1 WHEN 'en_attente' THEN 2 ELSE 3 END,w.updated_at DESC");$q->execute([$personnelId]);$stages=$q->fetchAll(PDO::FETCH_ASSOC);
 $q=$pdo->prepare("SELECT c.id,c.reference,c.document_id,c.objet,c.montant_ht,c.statut,c.created_at,c.signe_banamur_at,c.signe_prestataire_at,c.signature_banamur IS NOT NULL signe_banamur,c.signature_prestataire IS NOT NULL signe_prestataire,ch.code chantier_code,ch.titre chantier_titre,COALESCE(NULLIF(f.nom_commercial,''),f.raison_sociale,CONCAT(f.person_first_name,' ',f.person_last_name)) fournisseur_nom FROM contrat_sous_traitance c JOIN chantier_banamur ch ON ch.id=c.chantier_id JOIN fournisseur_banamur f ON f.id_fournisseur=c.fournisseur_id WHERE c.signataire_banamur_personnel_id=? ORDER BY COALESCE(c.signe_banamur_at,c.updated_at) DESC");$q->execute([$personnelId]);$contracts=$q->fetchAll(PDO::FETCH_ASSOC);
 $q=$pdo->prepare("SELECT r.id,r.paiement_id,r.decision,r.observations,r.created_at,r.updated_at,r.signe_banamur_at,r.signe_sous_traitant_at,r.signature_banamur IS NOT NULL signe_banamur,r.signature_sous_traitant IS NOT NULL signe_sous_traitant,p.type_paiement,p.avancement_cumule,p.montant_net,p.fiche_id,p.statut_financier,fd.num_fiche,fd.conforme,fd.approuve,fd.etat_fiche,fd.decaisse,COALESCE((SELECT SUM(ff.montant_fiche) FROM fiche_decaissement ff WHERE ff.contract_payment_id=p.id AND ff.decaisse=1),0) montant_decaisse,c.id contrat_id,c.reference,c.objet,ch.code chantier_code,ch.titre chantier_titre,COALESCE(NULLIF(f.nom_commercial,''),f.raison_sociale,CONCAT(f.person_first_name,' ',f.person_last_name)) fournisseur_nom FROM contrat_reception_pv r JOIN contrat_sous_traitance_paiement p ON p.id=r.paiement_id LEFT JOIN fiche_decaissement fd ON fd.id_fiche=p.fiche_id JOIN contrat_sous_traitance c ON c.id=p.contrat_id JOIN chantier_banamur ch ON ch.id=c.chantier_id JOIN fournisseur_banamur f ON f.id_fournisseur=c.fournisseur_id WHERE r.signataire_banamur_personnel_id=? ORDER BY COALESCE(r.signe_banamur_at,r.updated_at) DESC");$q->execute([$personnelId]);$pvs=$q->fetchAll(PDO::FETCH_ASSOC);
}
