$allowed=$focusType==='contrat'?array_column($contracts,'id'):array_column($pvs,'id');if(!$focusId||!in_array($focusId,array_map('intval',$allowed),true)){$focusType='';$focusId=0;}
$history=[];if($focusId){$q=$pdo->prepare("SELECT h.*,COALESCE(NULLIF(TRIM(CONCAT(COALESCE(u.prenom,''),' ',COALESCE(u.nom,''))),''),p.nom_personnel_soignant,'Système Finéa') acteur_nom FROM contrat_signature_historique h LEFT JOIN user_devis_banamur u ON u.id=h.acteur_user_id LEFT JOIN personnel p ON p.id_personnel_soignant=h.signataire_personnel_id WHERE h.document_type=? AND h.document_id=? ORDER BY h.created_at DESC,h.id DESC");$q->execute([$focusType,$focusId]);$history=$q->fetchAll(PDO::FETCH_ASSOC);$sourceRows=$focusType==='contrat'?$contracts:$pvs;$focused=null;foreach($sourceRows as $sourceRow)if((int)$sourceRow['id']===$focusId){$focused=$sourceRow;break;}if($focused){$actions=array_column($history,'action');$history[]=['action'=>'document_cree','acteur_nom'=>'Système Finéa','created_at'=>$focused['created_at']];if(!empty($focused['signe_banamur_at'])&&!in_array('signe_banamur',$actions,true))$history[]=['action'=>'signe_banamur','acteur_nom'=>'Donnée historique','created_at'=>$focused['signe_banamur_at']];$subDate=$focusType==='contrat'?($focused['signe_prestataire_at']??null):($focused['signe_sous_traitant_at']??null);$subAction=$focusType==='contrat'?'signe_prestataire':'signe_sous_traitant';if($subDate&&!in_array($subAction,$actions,true))$history[]=['action'=>$subAction,'acteur_nom'=>'Donnée historique','created_at'=>$subDate];usort($history,fn($a,$b)=>strcmp((string)$b['created_at'],(string)$a['created_at']));}}
