EB <?=$h($pv['num_fiche']?:'non encore créée')?> :</b> <?=$h($febState)?></div><div class="mt-4 flex flex-wrap gap-2"><a href="reception.php?paiement_id=<?=(int)$pv['paiement_id']?>" class="rounded-xl contract-primary px-4 py-2 font-bold"><?=(int)$pv['signe_banamur']?(empty($pv['fiche_id'])?'Finaliser et soumettre la FEB':'Voir le PV'):'Ouvrir et signer'?></a><a target="_blank" href="pv.php?paiement_id=<?=(int)$pv['paiement_id']?>" class="rounded-xl border px-4 py-2 font-bold">Aperçu</a><a href="?focus=pv-<?=(int)$pv['id']?>#historique" class="rounded-xl border contract-soft px-4 py-2 font-bold contract-reference">Historique</a></div></article><?php endforeach;?><?php if(!$pvs):?><p class="rounded-xl bg-slate-50 p-8 text-center text-slate-500 lg:col-span-2">Aucun PV ne vous est actuellement attribué.</p><?php endif;?></div></section>
